package main

import ("encoding/json";"fmt";"net/http")

type Item struct { ID int `json:"id"`; Name string `json:"name"` }
func health(w http.ResponseWriter, r *http.Request){w.Header().Set("Content-Type","application/json");_ = json.NewEncoder(w).Encode(map[string]string{"status":"ok"})}
func main(){http.HandleFunc("/health",health);fmt.Println("API starter: add routes, domain validation, persistence, auth, timeouts, and tests") }
